function lock(){if(ST)return;var b=document.body,h=document.documentElement,y=window.scrollY||h.scrollTop||0;ST={y:y,b:b.getAttribute('style'),h:h.getAttribute('style')};h.style.overflow='hidden';b.style.overflow='hidden';b.style.position='fixed';b.style.top=(-y)+'px';b.style.left='0';b.style.right='0';b.style.width='100%';}
function unlock(){if(!ST)return;var b=document.body,h=document.documentElement,s=ST;ST=null;if(s.b!=null)b.setAttribute('style',s.b);else b.removeAttribute('style');if(s.h!=null)h.setAttribute('style',s.h);else h.removeAttribute('style');window.scrollTo(0,s.y);}
var CSS='#cbsVw{position:fixed;inset:0;z-index:'+Z+';background:#1e2022;display:flex;flex-direction:column;font-family:system-ui,-apple-system,sans-serif;color:#fff}'+
'#cbsVw .vb{display:flex;align-items:center;gap:8px;padding:10px 12px;padding-top:calc(10px + env(safe-area-inset-top,0px));background:#2b2e31;flex:none;flex-wrap:wrap}'+
