function key(e){if(!O)return;if(e.key==='Escape'){e.stopImmediatePropagation();e.preventDefault();close();}else if(e.key==='ArrowLeft'&&IX>0){e.stopImmediatePropagation();IX--;show();}else if(e.key==='ArrowRight'&&IX<L.length-1){e.stopImmediatePropagation();IX++;show();}}
