 window.addEventListener('keydown',key,true);
 try{history.pushState({cbsVw:1},'');PUSHED=true;window.addEventListener('popstate',pop);}catch(x){PUSHED=false;}}
function close(){if(!O)return;window.removeEventListener('keydown',key,true);window.removeEventListener('popstate',pop);var p=PUSHED;PUSHED=false;TOK=null;try{if(document.fullscreenElement)document.exitFullscreen();}catch(x){}O.remove();O=null;unlock();if(p){try{history.back();}catch(x){}}}
function show(){if(!O)return;var f=L[IX]||{},k=kind(f),B=O.querySelector('.vbody');
 O.querySelector('.vn').textContent=f.n||'File';O.querySelector('.vc').textContent=L.length>1?(IX+1)+' of '+L.length:'';
 var pv=O.querySelector('[data-v=prev]'),nx=O.querySelector('[data-v=next]');pv.style.display=nx.style.display=L.length>1?'':'none';pv.disabled=IX===0;nx.disabled=IX===L.length-1;
 var dl=O.querySelector('[data-v=dl]');dl.href=prox(f.u);dl.setAttribute('download',f.n||'');
 var A=O.querySelector('.va');A.innerHTML='';(OPTS.actions||[]).forEach(function(a){if(!a||!a.label||typeof a.onClick!=='function')return;var b=document.createElement('button');b.type='button';b.textContent=a.label;b.onclick=function(){var cur=L[IX];close();setTimeout(function(){try{a.onClick(cur);}catch(x){}},0);};A.appendChild(b);});
 B.innerHTML='';B.scrollTop=0;var tok={};TOK=tok;
 function msg(t){var d=document.createElement('div');d.className='vmsg';d.textContent=t;B.appendChild(d);return d;}
 if(k==='img'){var im=document.createElement('img');im.alt=f.n||'';im.src=prox(f.u);B.appendChild(im);}
 else if(k==='video'){var vd=document.createElement('video');vd.controls=true;vd.playsInline=true;vd.src=prox(f.u);B.appendChild(vd);}
 else if(k==='pdf'){var m=msg('Loading\u2026');pdfLib(function(lib){if(TOK!==tok)return;if(!lib){m.textContent='This PDF could not be shown here. Use Download.';return;}
  lib.getDocument({url:prox(f.u)}).promise.then(function(doc){if(TOK!==tok)return;m.remove();var w=Math.max(200,Math.min(B.clientWidth-24,1400)),i=1;
   (function next(){if(TOK!==tok||i>doc.numPages)return;doc.getPage(i).then(function(pg){var sc=w/pg.getViewport({scale:1}).width,dpr=Math.min(window.devicePixelRatio||1,2),vp=pg.getViewport({scale:sc*dpr});var c=document.createElement('canvas');c.width=Math.floor(vp.width);c.height=Math.floor(vp.height);c.style.width=Math.floor(vp.width/dpr)+'px';if(TOK!==tok)return null;B.appendChild(c);return pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;}).then(function(){i++;next();},function(){i++;next();});})();
  },function(){if(TOK===tok)m.textContent='This PDF could not be shown here. Use Download.';});});}
 else if(k==='office')msg(OPTS.noOffice?'Tap Download to open this file.':'Word, Excel and PowerPoint files open in Office. Use Download to get a copy.');
 else msg('There is no preview for this type of file. Use Download.');}
function open(o){o=o||{};if(!o.u)return;var f={u:o.u,n:o.n||nameOf(o.u)},k=kind(f);
 if(k==='office'&&!o.noOffice){window.open(f.u,'_blank','noopener');return;}
 OPTS=o;var ok=function(x){return x&&x.u&&(kind(x)!=='office'||o.noOffice)&&kind(x)!=='other';};
 L=(Array.isArray(o.list)?o.list:[]).filter(ok).map(function(x){return {u:x.u,n:x.n||nameOf(x.u)};});
 IX=-1;for(var i=0;i<L.length;i++){if(L[i].u===f.u){IX=i;break;}}if(IX<0){L=[f];IX=0;}
